      function copyTextWithFallback(text) {
        var textarea = document.createElement('textarea');
        textarea.value = text;
        textarea.setAttribute('readonly', 'true');
        textarea.style.position = 'fixed';
        textarea.style.left = '-9999px';
        textarea.style.top = '0';
        textarea.style.opacity = '0';
        document.body.appendChild(textarea);
        textarea.focus();
        textarea.select();
        textarea.setSelectionRange(0, textarea.value.length);

        try {
          return document.execCommand('copy');
        } catch (error) {
          return false;
        } finally {
          textarea.remove();
        }
      }

      document.addEventListener('click', function (event) {
        var copyButton = event.target.closest('.code-copy-button');
        if (copyButton) {
          var code = copyButton.parentElement && copyButton.parentElement.querySelector('code');
          var codeText = code ? code.textContent || '' : '';
          var copied = false;

          event.preventDefault();
          event.stopPropagation();

          if (!codeText) return;

          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(codeText).then(function () {
              copyButton.dataset.state = 'copied';
              copyButton.setAttribute('aria-label', 'Code copied');
              window.setTimeout(function () {
                delete copyButton.dataset.state;
                copyButton.setAttribute('aria-label', 'Copy code');
              }, 1200);
            }).catch(function () {
              copied = copyTextWithFallback(codeText);
              copyButton.dataset.state = copied ? 'copied' : 'failed';
              copyButton.setAttribute('aria-label', copied ? 'Code copied' : 'Copy failed');
              window.setTimeout(function () {
                delete copyButton.dataset.state;
                copyButton.setAttribute('aria-label', 'Copy code');
              }, 1200);
            });
            return;
          }

          copied = copyTextWithFallback(codeText);
          copyButton.dataset.state = copied ? 'copied' : 'failed';
          copyButton.setAttribute('aria-label', copied ? 'Code copied' : 'Copy failed');
          window.setTimeout(function () {
            delete copyButton.dataset.state;
            copyButton.setAttribute('aria-label', 'Copy code');
          }, 1200);
          return;
        }

        var link = event.target.closest('a[href^="#"]');
        if (!link) return;
        var id = decodeURIComponent(link.getAttribute('href').slice(1));
        var target = document.getElementById(id);
        if (!target) return;
        event.preventDefault();
        target.scrollIntoView({ block: 'center' });
        target.classList.add('wowmd-highlight-located');
        window.setTimeout(function () {
          target.classList.remove('wowmd-highlight-located');
        }, 900);
        history.replaceState(null, '', '#' + encodeURIComponent(id));
      });
